
/**
 * Client
**/

import * as runtime from './runtime/library.js';
import $Types = runtime.Types // general types
import $Public = runtime.Types.Public
import $Utils = runtime.Types.Utils
import $Extensions = runtime.Types.Extensions
import $Result = runtime.Types.Result

export type PrismaPromise<T> = $Public.PrismaPromise<T>


/**
 * Model User
 * 
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model MfaDevice
 * 
 */
export type MfaDevice = $Result.DefaultSelection<Prisma.$MfaDevicePayload>
/**
 * Model Session
 * 
 */
export type Session = $Result.DefaultSelection<Prisma.$SessionPayload>
/**
 * Model LoginHistory
 * 
 */
export type LoginHistory = $Result.DefaultSelection<Prisma.$LoginHistoryPayload>
/**
 * Model AuthPolicy
 * Lockout, rate limiting, password strength and session timeouts are CONFIG,
 * not code (PDF 4). Changing one is an audited CONFIGURATION_CHANGES event.
 */
export type AuthPolicy = $Result.DefaultSelection<Prisma.$AuthPolicyPayload>
/**
 * Model Role
 * 
 */
export type Role = $Result.DefaultSelection<Prisma.$RolePayload>
/**
 * Model Permission
 * 
 */
export type Permission = $Result.DefaultSelection<Prisma.$PermissionPayload>
/**
 * Model RolePermission
 * 
 */
export type RolePermission = $Result.DefaultSelection<Prisma.$RolePermissionPayload>
/**
 * Model UserRole
 * 
 */
export type UserRole = $Result.DefaultSelection<Prisma.$UserRolePayload>
/**
 * Model RoleScopeGrant
 * Dimension-scoped grants (PDF 5). dimension_value_id = NULL means "all values".
 * DENY always wins over ALLOW (resolution order in lib/rbac/scope.ts).
 */
export type RoleScopeGrant = $Result.DefaultSelection<Prisma.$RoleScopeGrantPayload>
/**
 * Model Delegation
 * PDF 4: delegated authority. `expiresAt` is MANDATORY and validated in code -
 * an open-ended delegation is rejected, not merely discouraged.
 */
export type Delegation = $Result.DefaultSelection<Prisma.$DelegationPayload>
/**
 * Model AccessReview
 * 
 */
export type AccessReview = $Result.DefaultSelection<Prisma.$AccessReviewPayload>
/**
 * Model AccessReviewItem
 * 
 */
export type AccessReviewItem = $Result.DefaultSelection<Prisma.$AccessReviewItemPayload>
/**
 * Model Organization
 * 
 */
export type Organization = $Result.DefaultSelection<Prisma.$OrganizationPayload>
/**
 * Model Location
 * 
 */
export type Location = $Result.DefaultSelection<Prisma.$LocationPayload>
/**
 * Model Department
 * 
 */
export type Department = $Result.DefaultSelection<Prisma.$DepartmentPayload>
/**
 * Model CostCentre
 * 
 */
export type CostCentre = $Result.DefaultSelection<Prisma.$CostCentrePayload>
/**
 * Model Project
 * 
 */
export type Project = $Result.DefaultSelection<Prisma.$ProjectPayload>
/**
 * Model FundingSource
 * 
 */
export type FundingSource = $Result.DefaultSelection<Prisma.$FundingSourcePayload>
/**
 * Model Currency
 * 
 */
export type Currency = $Result.DefaultSelection<Prisma.$CurrencyPayload>
/**
 * Model ExchangeRate
 * 
 */
export type ExchangeRate = $Result.DefaultSelection<Prisma.$ExchangeRatePayload>
/**
 * Model MasterDataChangeRequest
 * 
 */
export type MasterDataChangeRequest = $Result.DefaultSelection<Prisma.$MasterDataChangeRequestPayload>
/**
 * Model MasterDataVersion
 * 
 */
export type MasterDataVersion = $Result.DefaultSelection<Prisma.$MasterDataVersionPayload>
/**
 * Model ReasonCode
 * Reason codes for transaction categorization (PDF 62). Seeded as reference data.
 */
export type ReasonCode = $Result.DefaultSelection<Prisma.$ReasonCodePayload>
/**
 * Model ProductService
 * Lightweight product/service catalogue for revenue linkage (PDF 62).
 */
export type ProductService = $Result.DefaultSelection<Prisma.$ProductServicePayload>
/**
 * Model Account
 * Chart of Accounts — hierarchical, configurable per PDF §7.
 */
export type Account = $Result.DefaultSelection<Prisma.$AccountPayload>
/**
 * Model FinancialPeriod
 * Financial Periods — monthly/quarterly/annual with lifecycle and reopen control.
 */
export type FinancialPeriod = $Result.DefaultSelection<Prisma.$FinancialPeriodPayload>
/**
 * Model OpeningBalance
 * Opening Balances — one-sided/partial historical entries with verification status (PDF §2).
 */
export type OpeningBalance = $Result.DefaultSelection<Prisma.$OpeningBalancePayload>
/**
 * Model AccountBalanceSnapshot
 * Account Balance Snapshots — rebuildable cache for dashboard speed.
 */
export type AccountBalanceSnapshot = $Result.DefaultSelection<Prisma.$AccountBalanceSnapshotPayload>
/**
 * Model JournalEntry
 * JournalEntry — M4 double-entry core.
 */
export type JournalEntry = $Result.DefaultSelection<Prisma.$JournalEntryPayload>
/**
 * Model JournalLine
 * JournalLine — M4 double-entry core. Every line belongs to exactly one entry.
 */
export type JournalLine = $Result.DefaultSelection<Prisma.$JournalLinePayload>
/**
 * Model ReversalReasonCode
 * Reversal reason codes — seeded reference data for reversal/adjustment audit trail.
 */
export type ReversalReasonCode = $Result.DefaultSelection<Prisma.$ReversalReasonCodePayload>
/**
 * Model Transaction
 * Minimal Transaction for M3 period-lock trigger (expanded in M5).
 */
export type Transaction = $Result.DefaultSelection<Prisma.$TransactionPayload>
/**
 * Model Budget
 * Minimal Budget for M3 account relation (expanded in M9).
 */
export type Budget = $Result.DefaultSelection<Prisma.$BudgetPayload>
/**
 * Model BudgetLine
 * Minimal BudgetLine for M3 account relation (expanded in M9).
 */
export type BudgetLine = $Result.DefaultSelection<Prisma.$BudgetLinePayload>
/**
 * Model OrganizationMembership
 * 
 */
export type OrganizationMembership = $Result.DefaultSelection<Prisma.$OrganizationMembershipPayload>
/**
 * Model AuditLog
 * Append-only. There is no update path and no delete path - enforced by
 * database triggers (prisma/migrations/*_audit_guards), not by convention.
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>
/**
 * Model AuditChainHead
 * The single mutable row that anchors the hash chain. SELECT ... FOR UPDATE on
 * this row serialises concurrent audit appends, which is what makes the chain
 * gap-free: an aborted transaction rolls back the audit row and the head update
 * together, so a sequence number can never be consumed by a lost write.
 */
export type AuditChainHead = $Result.DefaultSelection<Prisma.$AuditChainHeadPayload>
/**
 * Model AuditChainCheckpoint
 * Daily seals. Verification is incremental: start from the last checkpoint
 * rather than replaying the whole chain every night.
 */
export type AuditChainCheckpoint = $Result.DefaultSelection<Prisma.$AuditChainCheckpointPayload>
/**
 * Model SecurityEvent
 * 
 */
export type SecurityEvent = $Result.DefaultSelection<Prisma.$SecurityEventPayload>
/**
 * Model IdempotencyKey
 * All financial POST/PATCH/DELETE routes require an idempotency key so a
 * double-click, a retry or a replayed offline action cannot post twice.
 */
export type IdempotencyKey = $Result.DefaultSelection<Prisma.$IdempotencyKeyPayload>
/**
 * Model Notification
 * 
 */
export type Notification = $Result.DefaultSelection<Prisma.$NotificationPayload>
/**
 * Model NotificationPreference
 * 
 */
export type NotificationPreference = $Result.DefaultSelection<Prisma.$NotificationPreferencePayload>

